def app_open_conf():
    global cbox_filepath_list, cbox_nr, userDIR, jcf_path, profile_names, cbox_sel
    str_list = {}
    count = 0
    a = 0
    file_lenght = 0
    read_err = False
    ftime = True

    if not platform.system() == "Windows":
        filepath = Path(str(userDIR) + "/.local/share/jsk/config.cf")
        newDIR = Path(str(userDIR) + "/.local/share/jsk")
    else:
        filepath = Path(str(userDIR) + "\\AppData\\Local\\jsk\\config.cf")
        newDIR = Path(str(userDIR) + "\\AppData\\Local\\jsk")

    if filepath.is_file():
        with open(filepath, 'r') as file:
            for line in file:
                str_list[count] = line.strip("\n")
                line_lenght = len(line.strip("\n"))
                file_lenght = file_lenght + line_lenght
                count += 1
        file.close()

        if file_lenght > 0:
            str_list[0] = str_list[0].lower()

        if file_lenght > 0 and str_list[0] == "joy:cv":
            for c in range(count):
                if c == 2:
                    FormFG_color.set(str_list[c])
                elif c == 3:
                    FormBG_color.set(str_list[c])
                elif c == 5:
                    MenuFG_color.set(str_list[c])
                elif c == 6:
                    MenuBG_color.set(str_list[c])
                elif c == 7:
                    MenuAFG_color.set(str_list[c])
                elif c == 8:
                    MenuABG_color.set(str_list[c])
                elif c == 10:
                    ButtonFG_color.set(str_list[c])
                elif c == 11:
                    ButtonDFG_color.set(str_list[c])
                elif c == 12:
                    ButtonBG_color.set(str_list[c])
                elif c == 13:
                    ButtonAFG_color.set(str_list[c])
                elif c == 14:
                    ButtonABG_color.set(str_list[c])
                elif c == 16:
                    cbox_sel = int(str_list[c])
                elif c == 17:
                    cbox_nr = int(str_list[c])
                elif c >= 18:
                    if cbox_nr > 0: # profils
                        jcf_path = Path(str_list[c])
                        open_jcf_name()
                        if not prof == "#err..084":
                            profile_names[a] = prof
                            cbox_filepath_list[a] = str_list[c]
                            a += 1
                        else:
                            profile_names[a] = "#err.. profile"
                            cbox_filepath_list[a] = str_list[c]
                            a += 1
                            read_err = True

                    if not jcf_path == "nil":
                        _profiles_.set(True)

            if a > 0:
                for c in range(a):
                    if c == 0:
                        cbox['values'] = [profile_names[0]]
                    else:
                        if ftime == True:
                            options = list(cbox['values'])
                            ftime = False
                        options.append(profile_names[c])
                        cbox['values'] = options

                cbox.current(cbox_sel)
                jcf_path = Path(cbox_filepath_list[cbox_sel])

                if read_err == False:
                    load_var()
                    re_j1_BTicons()

        else:
            print("incorrect config.cf file")

    if cbox_nr == 0: # profils
        cbox_filepath_list[0] = "nil"
        
    if cbox_nr > 1:
        if platform.system() == "Darwin":
            next1_menu.entryconfig(2, state='normal')
        else:
            Delete_Button.configure(state='normal')
    else:
        if platform.system() == "Darwin":
            next1_menu.entryconfig(2, state='disabled')
        else:
            Delete_Button.configure(state='disabled')

    SelProfName.set(cbox.get())

    if platform.system() == "Windows" or platform.system() == "Linux":
        canv1.itemconfig('menubar', outline=MenuBG_color.get(), fill=MenuBG_color.get())
        File_Button.configure(fg=MenuFG_color.get(), bg=MenuBG_color.get(), disabledforeground=ButtonDFG_color.get())
