    def KB_downFunc(self, event):
        if chngblok.get() == False and self.Key_INPUT.get() == True:
            chngblok.set(True)
            if platform.system() == "Linux":
                chngIMG = canv1.create_image(10,62, image=chng_img, anchor='nw', tag='pik')
            elif platform.system() == "Windows":
                chngIMG = canv1.create_image(12,63, image=chng_img, anchor='nw', tag='pik')
            elif platform.system() == "Darwin":
                chngIMG = canv1.create_image(10,38, image=chng_img, anchor='nw', tag='pik')

        if kb_4.get() == True:
            if self.Key_INPUT.get() == True and j1_selected.get() == True:
                self.CHKBOX_F_disabled.set(False)
                if kb_4_Main_butt.get() == True: # Main Button
                    kb_button_chk.set("")
                    kbForm_anim.set(0)
                    self.Key_INPUT.set(False)
                    kb_4_Main_butt.set(False)
                    self.kbs_lb.configure(fg='#6AC2E3')

