def re_chk_key_input(ev):
    if ev == "Caps_Lock":
        chk = "C-Lock"
    elif ev == "Return":
        chk = "Enter"
    elif ev == "KP_0":
        chk = "0"
    elif ev == "KP_1":
        chk = "1"
    elif ev == "KP_2":
        chk = "2"
    elif ev == "KP_3":
        chk = "3"
    elif ev == "KP_4":
        chk = "4"
    elif ev == "KP_5":
        chk = "5"
    elif ev == "KP_6":
        chk = "6"
    elif ev == "KP_7":
        chk = "7"
    elif ev == "KP_8":
        chk = "8"
    elif ev == "KP_9":
        chk = "9"
    elif ev == "BackSpace":
        chk = "BSpace"
    elif ev == "Shift_L":
        chk = "Shi_L"
    elif ev == "Shift_R":
        chk = "Shi_R"
    elif ev == "Control_L":
        chk = "Crt_L"
    elif ev == "Control_R":
        chk = "Crt_R"
    elif ev == "Escape":
        chk = "Esc"
    elif ev == "Prior":
        chk = "PgUp"
