def ShowMessage():
    result_question = messagebox.askquestion(title="Question", message="Do you want to save the last changes in profile?")
    if result_question == "yes":
        save_file()
    else:
        chngblok.set(False)
        canv1.delete('pik')

def app_cf_save():
    global cbox_filepath_list, cbox_nr, userDIR

    if not platform.system() == "Windows":
        filepath = Path(str(userDIR) + "/.local/share/jsk/config.cf")
        newDIR = Path(str(userDIR) + "/.local/share/jsk")
    else:
        filepath = Path(str(userDIR) + "\\AppData\\Local\\jsk\\config.cf")
        newDIR = Path(str(userDIR) + "\\AppData\\Local\\jsk")

    if filepath.is_file():
        TextFile = open(filepath, "w")
        TextFile.write("joy:cv" + "\n")
    # theme
        TextFile.write("*form colors" + "\n")
        TextFile.write(FormFG_color.get() + "\n")
        TextFile.write(FormBG_color.get() + "\n")
        TextFile.write("*menu colors" + "\n")
        TextFile.write(MenuFG_color.get() + "\n")
        TextFile.write(MenuBG_color.get() + "\n")
        TextFile.write(MenuAFG_color.get() + "\n")
        TextFile.write(MenuABG_color.get() + "\n")
        TextFile.write("*button colors" + "\n")
        TextFile.write(ButtonFG_color.get() + "\n")
        TextFile.write(ButtonDFG_color.get() + "\n")
        TextFile.write(ButtonBG_color.get() + "\n")
        TextFile.write(ButtonAFG_color.get() + "\n")
        TextFile.write(ButtonABG_color.get() + "\n")
        TextFile.write("*profileDATA" + "\n")
        TextFile.write(str(cbox.current()) + "\n")
        TextFile.write(str(cbox_nr) + "\n")
        if cbox_nr == 0:
            TextFile.write("nil")
        else:
            for n in range(cbox_nr):
                if n < cbox_nr:
                    TextFile.write(cbox_filepath_list[n] + "\n")
                else:
                    TextFile.write(cbox_filepath_list[n])

        TextFile.close()
    else:
        newDIR.mkdir(parents=True, exist_ok=True)
        TextFile = open(filepath, "x") # New file
        TextFile.write("joy:cv" + "\n")
    # theme
        TextFile.write("*form colors" + "\n")
        TextFile.write(FormFG_color.get() + "\n")
        TextFile.write(FormBG_color.get() + "\n")
        TextFile.write("*menu colors" + "\n")
        TextFile.write(MenuFG_color.get() + "\n")
        TextFile.write(MenuBG_color.get() + "\n")
        TextFile.write(MenuAFG_color.get() + "\n")
        TextFile.write(MenuABG_color.get() + "\n")
        TextFile.write("*button colors" + "\n")
        TextFile.write(ButtonFG_color.get() + "\n")
        TextFile.write(ButtonDFG_color.get() + "\n")
        TextFile.write(ButtonBG_color.get() + "\n")
        TextFile.write(ButtonAFG_color.get() + "\n")
        TextFile.write(ButtonABG_color.get() + "\n")
        TextFile.write("*profileDATA" + "\n")

        TextFile.write(str(cbox.current()) + "\n")
        TextFile.write(str(cbox_nr) + "\n")
        if cbox_nr == 0:
            TextFile.write("nil")
        else:
            for n in range(cbox_nr):
                if n < cbox_nr:
                    TextFile.write(cbox_filepath_list[n] + "\n")
                else:
                    TextFile.write(cbox_filepath_list[n])

        TextFile.close()

def end_app():
    app_cf_save()

    if chngblok.get() == True:
        ShowMessage()

    app_running.set(False)

def handle_input(event, gamepad_id):
    if event.type == pygame.JOYBUTTONDOWN:
        if gamepad_id == 0: # joy 1
            if event.button == 0:
                j1_Button1.set(True)
            elif event.button == 1:
                j1_Button2.set(True)
            elif event.button == 2:
                j1_Button3.set(True)
            elif event.button == 3:
                j1_Button4.set(True)
            elif event.button == 4:
                j1_Button5.set(True)
            elif event.button == 5:
                j1_Button6.set(True)
            elif event.button == 6:
                j1_Button7.set(True)
            elif event.button == 7:
                j1_Button8.set(True)
            elif event.button == 8:
                j1_Button9.set(True)
            elif event.button == 9:
                j1_Button10.set(True)
            elif event.button == 10:
                j1_Button11.set(True)
            elif event.button == 11:
                j1_Button12.set(True)
        if gamepad_id == 1: # joy 2
            if event.button == 0:
                j2_Button1.set(True)
            elif event.button == 1:
                j2_Button2.set(True)
            elif event.button == 2:
                j2_Button3.set(True)
            elif event.button == 3:
                j2_Button4.set(True)
            elif event.button == 4:
                j2_Button5.set(True)
            elif event.button == 5:
                j2_Button6.set(True)
            elif event.button == 6:
                j2_Button7.set(True)
            elif event.button == 7:
                j2_Button8.set(True)
            elif event.button == 8:
                j2_Button9.set(True)
            elif event.button == 9:
                j2_Button10.set(True)
            elif event.button == 10:
                j2_Button11.set(True)
            elif event.button == 11:
                j2_Button12.set(True)

    elif event.type == pygame.JOYBUTTONUP:
        if gamepad_id == 0: # joy 1
            if event.button == 0:
                j1_Button1.set(False)
            elif event.button == 1:
                j1_Button2.set(False)
            elif event.button == 2:
                j1_Button3.set(False)
            elif event.button == 3:
                j1_Button4.set(False)
            elif event.button == 4:
                j1_Button5.set(False)
            elif event.button == 5:
                j1_Button6.set(False)
            elif event.button == 6:
                j1_Button7.set(False)
            elif event.button == 7:
                j1_Button8.set(False)
            elif event.button == 8:
                j1_Button9.set(False)
            elif event.button == 9:
                j1_Button10.set(False)
            elif event.button == 10:
                j1_Button11.set(False)
            elif event.button == 11:
                j1_Button12.set(False)
        if gamepad_id == 1: # joy 2
            if event.button == 0:
                j2_Button1.set(False)
            elif event.button == 1:
                j2_Button2.set(False)
            elif event.button == 2:
                j2_Button3.set(False)
            elif event.button == 3:
                j2_Button4.set(False)
            elif event.button == 4:
                j2_Button5.set(False)
            elif event.button == 5:
                j2_Button6.set(False)
            elif event.button == 6:
                j2_Button7.set(False)
            elif event.button == 7:
                j2_Button8.set(False)
            elif event.button == 8:
                j2_Button9.set(False)
            elif event.button == 9:
                j2_Button10.set(False)
            elif event.button == 10:
                j2_Button11.set(False)
            elif event.button == 11:
                j2_Button12.set(False)

    elif event.type == pygame.JOYAXISMOTION:
        if gamepad_id == 0: # joy 1
            axis = event.axis
            if axis == 0:
                value = event.value * j1_stick1_speed.get()
                j1_Stick_1_x.set(value)
                j1_Stick_1_Detct_x.set(event.value)
            elif axis == 1:
                value = event.value * j1_stick1_speed.get()
                j1_Stick_1_y.set(value)
                j1_Stick_1_Detct_y.set(event.value)
            if axis == 2:
                value = event.value * j1_stick2_speed.get()
                j1_Stick_2_x.set(value)
                j1_Stick_2_Detct_x.set(event.value)
            elif axis == 3:
                value = event.value * j1_stick2_speed.get()
                j1_Stick_2_y.set(value)
                j1_Stick_2_Detct_y.set(event.value)
            elif axis == 4:
                j1_xbox_L_Detct.set(event.value)
            elif axis == 5:
                j1_xbox_R_Detct.set(event.value)

        if gamepad_id == 1: # joy 2
            axis = event.axis
            if axis == 0:
                value = event.value * j2_stick1_speed.get()
                j2_Stick_1_x.set(value)
                j2_Stick_1_Detct_x.set(event.value)
            elif axis == 1:
                value = event.value * j2_stick1_speed.get()
                j2_Stick_1_y.set(value)
                j2_Stick_1_Detct_y.set(event.value)
            if axis == 2:
                value = event.value * j2_stick2_speed.get()
                j2_Stick_2_x.set(value)
                j2_Stick_2_Detct_x.set(event.value)
            elif axis == 3:
                value = event.value * j2_stick2_speed.get()
                j2_Stick_2_y.set(value)
                j2_Stick_2_Detct_y.set(event.value)
            elif axis == 4:
                j2_xbox_R_Detct.set(event.value)
            elif axis == 5:
                j2_xbox_L_Detct.set(event.value)


    elif event.type == pygame.JOYHATMOTION:
        direction = "nil"
        if gamepad_id == 0: #joy1
            hat_value = event.value

            if hat_value == (0, 1):
                direction = "Up"
            elif hat_value == (0, -1):
                direction = "Down"
            elif hat_value == (1, 0):
                direction = "Right"
            elif hat_value == (-1, 0):
                direction = "Left"
            elif hat_value == (1, 1):
                direction = "Up-Right"
            elif hat_value == (-1, 1):
                direction = "Up-Left"
            elif hat_value == (1, -1):
                direction = "Down-Right"
            elif hat_value == (-1, -1):
                direction = "Down-Left"
            j1_Direction.set(direction)

        if gamepad_id == 1: #joy2
            hat_value = event.value
    
            if hat_value == (0, 1):
                direction = "Up"
            elif hat_value == (0, -1):
                direction = "Down"
            elif hat_value == (1, 0):
                direction = "Right"
            elif hat_value == (-1, 0):
                direction = "Left"
            elif hat_value == (1, 1):
                direction = "Up-Right"
            elif hat_value == (-1, 1):
                direction = "Up-Left"
            elif hat_value == (1, -1):
                direction = "Down-Right"
            elif hat_value == (-1, -1):
                direction = "Down-Left"
            j2_Direction.set(direction)

