canv1.place(x=-1, y=-1)

j1_selected = tk.BooleanVar(root, True)
j2_selected = tk.BooleanVar(root, False)

j1_pluged = tk.BooleanVar(root, False)
j2_pluged = tk.BooleanVar(root, False)


def change_js1():
    j2_selected.set(False)
    j1_selected.set(True)
    if platform.system() == "Windows" or platform.system() == "Linux":
        HideJoys_subMENU()
        JoySet_Button.configure(relief='flat')
        Menu_AC.set(False)
        Joy1_Button.configure(image=rb_icon_True)
        Joy2_Button.configure(image=rb_icon_False)
    else:
        next2_menu.entryconfig(0, image=rb_icon_True)
        next2_menu.entryconfig(1, image=rb_icon_False)

    if j1_pluged.get() == True:
        info_lb.configure(text="Joystick 1: " + joystick1.get_name())
    else:
        info_lb.configure(text="Joystick 1 unplugged;")

    re_j1_BTicons()

