def open_file():
    global cbox_filepath_list, cbox_nr, jcf_path, cbox, prof, profile_names, cbox_sel

    if platform.system() == "Windows" or platform.system() == "Linux":
        HideFile_subMENU()
        File_Button.configure(relief='flat')
        Menu_AC.set(False)

    str_list = {}
    count = 0
    file_lenght = 0
    n = 2

    types = [("Joystick config. files", "*.jcf"),
             ("All files", "*.*")]

    file = filedialog.askopenfile(title = "Open File",
                                  initialdir = userDIR,
                                  defaultextension=".jcf",
                                  filetypes=types)
    if file is None:
        return
    jcf_path = Path(file.name)

    with open(jcf_path, 'r') as file:
        for line in file:
            str_list[count] = line.strip("\n")
            line_lenght = len(line.strip("\n"))
            file_lenght = file_lenght + line_lenght
            count += 1
    file.close()

    chk = str_list[0].split(":")
    chk[0] = chk[0].lower()

    if file_lenght > 0 and chk[0] == "#jcf":
        if not chk[1] == "":
            prof = chk[1]
        else:
            prof = "untitled"
    else:
        prof = "#err..084"
        messagebox.showerror(title="Error", message="incorrect file")


    if not prof == "#err..084":
        if not cbox_nr == 0:
            cbox_filepath_list[cbox_nr] = file.name
            profile_names[cbox_nr] = prof
            cbox['values'] += (prof,)
            cbox.current(cbox_nr)
            cbox_nr += 1
        else:
            tmp_Items = []
            tmp_Items.append(prof)
            cbox['values'] = tmp_Items
            cbox.set(prof)
            cbox_filepath_list[0] = file.name
            cbox_nr = 1
            cbox_sel = 0

