def open_jcf_name():
    global cbox_nr, jcf_path, cbox, prof
    str_list = {}
    count = 0
    file_lenght = 0

    if jcf_path.is_file():
        with open(jcf_path, 'r') as file:
            for line in file:
                str_list[count] = line.strip("\n")
                line_lenght = len(line.strip("\n"))
                file_lenght = file_lenght + line_lenght
                count += 1
        file.close()

        chk = str_list[0].split(":")
        chk[0] = chk[0].lower()

        if file_lenght > 0 and chk[0] == "#jcf":
            if not chk[1] == "":
                prof = chk[1]
            else:
                prof = "untitled"
        else:
            print("incorrect jcf file")
            prof = "#err..084"
    else:
        prof = "#err..084"

