def ShowFile_subMENU():
    global sub1F_x, sub1F_y, sub2F_x, sub2F_y, sub3F_x, sub3F_y, sub4F_x, sub4F_y
    Open_Button.place(x=sub1F_x, y=sub1F_y)
    Save_Button.place(x=sub2F_x, y=sub2F_y)
    SaveAs_Button.place(x=sub3F_x, y=sub3F_y)
    Exit_Button.place(x=sub4F_x, y=sub4F_y)

def HideFile_subMENU():
    Open_Button.place_forget()
    Save_Button.place_forget()
    SaveAs_Button.place_forget()
    Exit_Button.place_forget()

def ShowEdit_subMENU():
    global sub1E_x, sub1E_y, sub2E_x, sub2E_y, sub3E_x, sub3E_y, sub4E_x, sub4E_y
    NewProfile_Button.place(x=sub1E_x, y=sub1E_y)
    Rename_Button.place(x=sub2E_x, y=sub2E_y)
    Delete_Button.place(x=sub3E_x, y=sub3E_y)
    ThCol_Button.place(x=sub4E_x, y=sub4E_y)

def HideEdit_subMENU():
    NewProfile_Button.place_forget()
    Rename_Button.place_forget()
    Delete_Button.place_forget()
    ThCol_Button.place_forget()

def ShowJoys_subMENU():
    global sub1J_x, sub1J_y, sub2J_x, sub2J_y
    Joy1_Button.place(x=sub1J_x, y=sub1J_y)
    Joy2_Button.place(x=sub2J_x, y=sub2J_y)

def HideJoys_subMENU():
    Joy1_Button.place_forget()
    Joy2_Button.place_forget()

Menu_AC = tk.BooleanVar(root, False)

def CloseMENU(event):
    if Menu_AC.get() == True:
        Menu_AC.set(False)
        File_Button.configure(relief='flat')
        Edit_Button.configure(relief='flat')
        JoySet_Button.configure(relief='flat')
        HideFile_subMENU()
        HideEdit_subMENU()
        HideJoys_subMENU()

def OpenFile_MENU():
    if Menu_AC.get() == False:
        File_Button.configure(relief='sunken')
        Menu_AC.set(True)
        ShowFile_subMENU()
    else:
        File_Button.configure(relief='flat')
        Menu_AC.set(False)
        HideFile_subMENU()

def OpenEdit_MENU():
    if Menu_AC.get() == False:
        Edit_Button.configure(relief='sunken')
        Menu_AC.set(True)
        ShowEdit_subMENU()
    else:
        Edit_Button.configure(relief='flat')
        Menu_AC.set(False)
        HideEdit_subMENU()

def OpenJoySet_MENU():
    if Menu_AC.get() == False:
        JoySet_Button.configure(relief='sunken')
        Menu_AC.set(True)
        ShowJoys_subMENU()
    else:
        JoySet_Button.configure(relief='flat')
        Menu_AC.set(False)
        HideJoys_subMENU()

def SET_1_MENU(xy):
    if Menu_AC.get() == True:
        File_Button.configure(relief='sunken')
        ShowFile_subMENU()

        Edit_Button.configure(relief='flat')
        JoySet_Button.configure(relief='flat')
        HideEdit_subMENU()
        HideJoys_subMENU()

def SET_2_MENU(xy):
    if Menu_AC.get() == True:
        Edit_Button.configure(relief='sunken')
        ShowEdit_subMENU()

        File_Button.configure(relief='flat')
        JoySet_Button.configure(relief='flat')
        HideFile_subMENU()
        HideJoys_subMENU()

def SET_3_MENU(xy):
    if Menu_AC.get() == True:
        JoySet_Button.configure(relief='sunken')
        ShowJoys_subMENU()

        File_Button.configure(relief='flat')
        Edit_Button.configure(relief='flat')
        HideFile_subMENU()
        HideEdit_subMENU()

